<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';
import type {AlbumDraft,CreationDraft,FitnessEntryDraft,PlaylistDraft} from '@xvyin/contracts';
import {api,ApiError,dateTime,errorMessage,formatBytes,visibilityLabel,type Collection,type DraftRecord} from './api';
import RecordEditor from './components/RecordEditor.vue';import MediaLibrary from './components/MediaLibrary.vue';import SettingsPanel from './components/SettingsPanel.vue';import ModerationPanel from './components/ModerationPanel.vue';import ReleasePanel,{type ReleaseChange} from './components/ReleasePanel.vue';
type Editable=CreationDraft|AlbumDraft|FitnessEntryDraft|PlaylistDraft;
interface Stats{content:{creations:number|null;albums:number|null;fitness:number|null;playlists:number|null};moderation:{pending:number|null;contacts:number|null};media:{usedBytes:number;reservedBytes:number;limitBytes:number};traffic:null;activeReleaseId:string|null}
const router=useRouter();const route=useRoute();const booting=ref(true);const authenticated=ref(false);const everAuthenticated=ref(false);const username=ref('');const loginUsername=ref('');const password=ref('');const loginBusy=ref(false);const authIssue=ref('');const authMode=ref<'login'|'request'|'confirm'>('login');const newPassword=ref('');const confirmation=ref('');const resetCode=ref('');const recoverySent=ref(false);const previewReleaseId=ref<string|null>(null);const sidebarOpen=ref(false);
const issue=ref('');const notice=ref('');const loading=ref(false);const saving=ref(false);const records=ref<DraftRecord<Editable>[]>([]);const query=ref('');const status=ref('all');const cursor=ref<string>();const statistics=ref<Stats|null>(null);const dirty=ref(false);const editorRevision=ref(0);const releaseOpen=ref(false);const releaseChanges=ref<ReleaseChange[]|undefined>();
const nav=[{key:'overview',label:'总览',icon:'◫'},{key:'creations',label:'创作',icon:'✎'},{key:'albums',label:'摄影',icon:'▧'},{key:'fitness',label:'健身',icon:'⌁'},{key:'playlists',label:'歌单',icon:'♫'},{key:'comments',label:'评论审核',icon:'≋'},{key:'media',label:'媒体',icon:'▦'},{key:'statistics',label:'统计',icon:'↗'},{key:'settings',label:'设置',icon:'⚙'}];
const parts=computed(()=>route.path.split('/').filter(Boolean));const section=computed(()=>nav.some(item=>item.key===parts.value[0])?parts.value[0]!:'overview');const collection=computed(()=>['creations','albums','fitness','playlists'].includes(section.value)?section.value as Collection:null);const editorId=computed(()=>collection.value&&parts.value[1]?parts.value[1]:null);const selectedRecord=computed(()=>records.value.find(row=>row.id===editorId.value)??null);const title=computed(()=>nav.find(item=>item.key===section.value)?.label??'总览');
const descriptions:Record<string,string>={overview:'照看正在生长的个人网站。',creations:'文字、图片、音频与视频，在同一条创作里表达。',albums:'整理摄影系列，让画面有自己的顺序。',fitness:'真实日期，真实记录。',playlists:'管理首页的音乐与播放顺序。',comments:'让每一次公开交流，都经过你的确认。',media:'所有素材集中管理，内容只引用一份原件。',statistics:'只呈现已接入服务的真实数据。',settings:'维护网站资料、导航与管理员账户。'};
const filtered=computed(()=>records.value.filter(row=>(status.value==='all'||row.visibility===status.value)&&recordTitle(row).toLowerCase().includes(query.value.toLowerCase())));
function recordTitle(row:DraftRecord<Editable>){return 'name' in row.draft?row.draft.name:row.draft.title||'未命名草稿';}
function itemDescription(row:DraftRecord<Editable>){if('summary' in row.draft)return row.draft.summary;if('photos' in row.draft)return `${row.draft.photos.length} 张照片${'entryDate' in row.draft?` · ${row.draft.entryDate}`:''}`;if('tracks' in row.draft)return `${row.draft.tracks.length} 首曲目`;return '';}
async function establish(data:{username:string;csrfToken:string;previewReleaseId?:string|null},preview?:string|null){username.value=data.username;loginUsername.value=data.username;api.csrfToken=data.csrfToken;authenticated.value=true;everAuthenticated.value=true;previewReleaseId.value=preview??data.previewReleaseId??null;authIssue.value='';password.value='';if(!records.value.length&&!dirty.value)await loadSection();}
async function bootstrap(){booting.value=true;const params=new URLSearchParams(window.location.search);const code=params.get('oobCode');if(code){resetCode.value=code;authMode.value='confirm';window.history.replaceState({},'',`${window.location.pathname}`);}try{const response=await api.request<{username:string;csrfToken:string}>('/auth/session');await establish(response.data,response.meta.previewReleaseId);}catch(error){if(!(error instanceof ApiError&&error.status===401))authIssue.value=errorMessage(error);}finally{booting.value=false;}}
async function submitAuth(){loginBusy.value=true;authIssue.value='';try{if(authMode.value==='login'){const response=await api.request<{username:string;csrfToken:string}>('/auth/login',{method:'POST',body:{username:loginUsername.value,password:password.value}});await establish(response.data,response.meta.previewReleaseId);}else if(authMode.value==='request'){await api.request('/auth/reset/request',{method:'POST',body:{username:loginUsername.value}});recoverySent.value=true;}else{if(newPassword.value!==confirmation.value)throw new Error('两次新密码不一致。');await api.request('/auth/reset/confirm',{method:'POST',body:{code:resetCode.value,newPassword:newPassword.value}});newPassword.value='';confirmation.value='';resetCode.value='';authMode.value='login';authIssue.value='密码已重设，请用新密码登录。';}}catch(error){authIssue.value=errorMessage(error);}finally{password.value='';loginBusy.value=false;}}
api.onExpired=()=>{authenticated.value=false;authMode.value='login';authIssue.value='会话已失效。重新登录后可以继续当前页面，未保存的编辑仍暂存在此标签页。';};
async function logout(){if(dirty.value&&!window.confirm('还有未保存的修改，退出会丢失这些修改。继续退出吗？'))return;try{await api.request('/auth/logout',{method:'POST',body:{}});authenticated.value=false;everAuthenticated.value=false;api.csrfToken='';records.value=[];statistics.value=null;dirty.value=false;previewReleaseId.value=null;}catch(error){issue.value=errorMessage(error);}}
function passwordChanged(){authenticated.value=false;authMode.value='login';api.csrfToken='';authIssue.value='密码已更新，所有管理员会话已撤销。请重新登录。';dirty.value=false;}
async function navigate(path:string){if(dirty.value&&!window.confirm('离开此页会放弃尚未保存的修改，继续吗？'))return;dirty.value=false;sidebarOpen.value=false;notice.value='';await router.push(path);}
let loadSequence=0;
async function loadSection(more=false){if(!authenticated.value)return;const sequence=++loadSequence;loading.value=true;issue.value='';try{if(collection.value){const response=await api.request<DraftRecord<Editable>[]>(`/admin/${collection.value}${more&&cursor.value?`?cursor=${encodeURIComponent(cursor.value)}`:''}`);if(sequence!==loadSequence)return;records.value=more?[...records.value,...response.data]:response.data;cursor.value=response.meta.nextCursor;}else if(section.value==='overview'||section.value==='statistics'){const response=await api.request<Stats>('/admin/statistics');if(sequence!==loadSequence)return;statistics.value=response.data;}}catch(error){if(sequence===loadSequence)issue.value=errorMessage(error);}finally{if(sequence===loadSequence)loading.value=false;}}
async function saveRecord(draft:Editable,publish:boolean){if(!collection.value)return;saving.value=true;issue.value='';notice.value='';try{const current=selectedRecord.value;const result=await api.request<DraftRecord<Editable>>(`/admin/${collection.value}${current?`/${current.id}`:''}`,{method:current?'PATCH':'POST',body:current?{draft,expectedVersion:current.version}:{draft}});const index=records.value.findIndex(row=>row.id===result.data.id);if(index>=0)records.value[index]=result.data;else records.value.unshift(result.data);dirty.value=false;editorRevision.value++;notice.value='草稿已保存。公开页面在确认发布后更新。';if(editorId.value==='new')await router.replace(`/${collection.value}/${result.data.id}`);if(publish)openRelease([{collection:collection.value,id:result.data.id,version:result.data.version,action:'publish'}]);}catch(error){issue.value=errorMessage(error);if(error instanceof ApiError&&error.status===409)issue.value+=' 请保留当前内容，重新读取并合并其他窗口的修改后再保存。';}finally{saving.value=false;}}
function openRelease(changes?:ReleaseChange[]){releaseChanges.value=changes;releaseOpen.value=true;}
function publishRecord(row:DraftRecord<Editable>,action:'publish'|'hide'){if(!collection.value)return;openRelease([{collection:collection.value,id:row.id,version:row.version,action}]);}
async function reloadEditor(){if(dirty.value&&!window.confirm('重新读取会放弃当前未保存内容，继续吗？'))return;await loadSection();dirty.value=false;editorRevision.value++;}
async function closePreview(){try{await api.request('/admin/preview/close',{method:'POST',body:{}});previewReleaseId.value=null;notice.value='已退出私有预览，新打开或刷新的网页将显示当前公开版本。';}catch(error){issue.value=errorMessage(error);}}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue='';}}
const removeNavigationGuard=router.beforeEach((to,from)=>{if(to.path!==from.path&&dirty.value){if(!window.confirm('离开此页会放弃尚未保存的修改，继续吗？'))return false;dirty.value=false;}return true;});
watch(section,()=>{query.value='';status.value='all';cursor.value=undefined;records.value=[];loadSection();});watch(editorId,()=>{dirty.value=false;issue.value='';});
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);bootstrap();});onBeforeUnmount(()=>{window.removeEventListener('beforeunload',beforeUnload);removeNavigationGuard();api.onExpired=undefined;});
</script>
<template><div v-if="booting" class="boot-screen" role="status"><span class="brand-mark">虚宁</span><p>正在确认管理员会话…</p></div><div v-else><div v-if="everAuthenticated" class="admin-shell" :inert="!authenticated"><button class="mobile-menu" aria-label="打开管理导航" @click="sidebarOpen=!sidebarOpen">☰</button><button v-if="sidebarOpen" class="sidebar-backdrop" aria-label="收起导航" @click="sidebarOpen=false"></button><aside class="sidebar" :class="{open:sidebarOpen}"><a class="brand" href="/admin/" @click.prevent="navigate('/overview')"><span class="brand-mark">虚宁</span><span>内容管理<small>XVYIN · STUDIO</small></span></a><nav aria-label="管理模块"><button v-for="item in nav" :key="item.key" :class="{active:section===item.key}" :aria-current="section===item.key?'page':undefined" @click="navigate(`/${item.key}`)"><span aria-hidden="true" class="nav-icon">{{item.icon}}</span>{{item.label}}<span v-if="item.key==='comments'&&statistics?.moderation.pending" class="nav-count">{{statistics.moderation.pending??'—'}}</span></button></nav><div class="sidebar-bottom"><a href="/" target="_blank" rel="noopener">打开网站 <span>↗</span></a><div class="account"><span class="avatar-initial">{{username.slice(0,1).toUpperCase()}}</span><div><strong>{{username}}</strong><small>管理员</small></div><button class="text-button" @click="logout">退出</button></div></div></aside><main class="admin-main"><div class="topbar"><span>管理后台 <span class="crumb">/</span> {{title}}<span v-if="editorId" class="crumb">/ {{editorId==='new'?'新建':'编辑'}}</span></span><div class="flex"><span v-if="dirty" class="unsaved-dot">未保存</span><button @click="openRelease()">发布记录</button></div></div><div v-if="previewReleaseId" class="preview-notice" role="status"><span>私有预览已开启 · <span class="mono">{{previewReleaseId}}</span>。此浏览器打开网站会显示候选内容。</span><button @click="closePreview">退出预览</button></div><div class="page-content"><header class="page-heading"><div><p class="eyebrow">{{section.toUpperCase()}}</p><h1>{{editorId?(editorId==='new'?`新建${title}`:`编辑${title}`):title}}</h1><p>{{descriptions[section]}}</p></div><button v-if="collection&&!editorId" class="primary" @click="navigate(`/${collection}/new`)">＋ 新建{{title}}</button><button v-if="editorId&&editorId!=='new'" @click="reloadEditor">重新读取</button></header><div v-if="issue" class="notice error mb24" role="alert">{{issue}} <button v-if="!editorId" class="text-button" @click="loadSection()">重试</button></div><div v-if="notice" class="notice success mb24" role="status">{{notice}}</div><p v-if="loading" class="loading" role="status">正在读取真实内容…</p><template v-else-if="collection"><RecordEditor v-if="editorId&&(editorId==='new'||selectedRecord)" :key="`${collection}/${editorId}/${editorRevision}`" :collection="collection" :record="selectedRecord" :busy="saving" @save="saveRecord" @cancel="navigate(`/${collection}`)" @dirty="dirty=$event"/><div v-else-if="editorId" class="empty"><h2>未找到这条内容</h2><p>它可能不在当前已加载列表中，或已无法访问。</p><button v-if="cursor" class="mt16" @click="loadSection(true)">继续查找下一页</button><button class="mt16" @click="navigate(`/${collection}`)">返回列表</button></div><template v-else><SettingsPanel v-if="collection==='fitness'" kind="fitness" class="mb40" @publish="openRelease" @dirty="dirty=$event"/><div class="toolbar"><label class="search"><span class="sr-only">搜索标题</span><input v-model="query" type="search" placeholder="搜索标题…"></label><label><span class="sr-only">发布状态</span><select v-model="status"><option value="all">全部状态</option><option value="draft">草稿</option><option value="published">已发布</option><option value="hidden">已隐藏</option></select></label><button @click="loadSection()">刷新</button></div><div v-if="!filtered.length" class="empty mt24"><span class="empty-symbol">{{collection==='playlists'?'♫':collection==='fitness'?'⌁':'✎'}}</span><h2>{{records.length?'没有匹配内容':`还没有${title}`}}</h2><p>{{records.length?'调整关键词或状态筛选，再试一次。':'从第一条真实内容开始，保存草稿后再预览和发布。'}}</p><button v-if="!records.length" class="primary mt24" @click="navigate(`/${collection}/new`)">新建{{title}}</button></div><div v-else class="record-table mt24"><div class="table-heading"><span>内容</span><span>状态</span><span>最近保存</span><span>操作</span></div><article v-for="row in filtered" :key="row.id" class="record-row"><div><button class="record-title" @click="navigate(`/${collection}/${row.id}`)">{{recordTitle(row)}}</button><p class="hint mt8 record-summary">{{itemDescription(row)||'尚未填写介绍'}}</p><small class="mono">版本 {{row.version}}<span v-if="row.lastPublishedRevisionId&&row.lastPublishedRevisionId!==row.draftRevisionId"> · 有未发布修改</span></small></div><span class="badge" :class="{green:row.visibility==='published'}">{{visibilityLabel(row.visibility)}}</span><small class="hint">{{dateTime(row.updatedAt)}}</small><div class="row-actions flex"><button @click="navigate(`/${collection}/${row.id}`)">编辑</button><button @click="publishRecord(row,'publish')">准备发布</button><button v-if="row.visibility==='published'" @click="publishRecord(row,'hide')">隐藏</button></div></article></div><button v-if="cursor" class="mt24" @click="loadSection(true)">加载更多</button></template></template><MediaLibrary v-else-if="section==='media'"/><ModerationPanel v-else-if="section==='comments'"/><SettingsPanel v-else-if="section==='settings'" kind="site" @publish="openRelease" @password-changed="passwordChanged" @dirty="dirty=$event"/><template v-else-if="statistics"><div class="stats-grid"><button v-for="key in (['creations','albums','fitness','playlists'] as const)" :key="key" class="stat-card" @click="navigate(`/${key}`)"><span>{{nav.find(item=>item.key===key)?.label}}</span><strong>{{statistics.content[key]??'—'}}</strong><small>{{statistics.content[key]===null?'统计待初始化':'已保存内容'}} <span>↗</span></small></button></div><div class="dashboard-grid mt24"><section class="panel"><div class="flex between"><h2>待处理</h2><span class="tiny-seal">日常</span></div><button class="dashboard-link mt24" @click="navigate('/comments')"><span>待审核留言</span><strong>{{statistics.moderation.pending??'—'}}</strong><span>→</span></button><button class="dashboard-link" @click="navigate('/comments')"><span>私密联系</span><strong>{{statistics.moderation.contacts??'—'}}</strong><span>→</span></button><div class="soft-note mt24"><p>访客免注册，留言经审核后公开。</p><p>创作、摄影和健身内容保存后，可在发布记录里完成预览与上线。</p></div></section><section class="panel"><h2>媒体空间</h2><p class="space-total mt24"><strong>{{formatBytes(statistics.media.usedBytes)}}</strong><span>/ {{formatBytes(statistics.media.limitBytes)}}</span></p><progress class="quota-progress mt24" :value="statistics.media.usedBytes+statistics.media.reservedBytes" :max="statistics.media.limitBytes"></progress><p class="hint mt16">上传预留 {{formatBytes(statistics.media.reservedBytes)}} · 单视频不超过 512 MB</p><button class="mt24" @click="navigate('/media')">管理媒体</button></section><section class="panel"><h2>公开版本</h2><p class="mono mt24">{{statistics.activeReleaseId??'尚未发布内容版本'}}</p><p class="hint mt16">这里显示后端当前生效的内容版本，发布记录会展示候选生成和切换结果。</p><button class="mt24" @click="openRelease()">查看发布记录</button></section><section class="panel"><h2>访问统计</h2><div class="unavailable-stat mt24">尚未接入</div><p class="hint mt16">暂未接入可用的真实流量来源，不显示访客数或访问趋势。</p></section></div><div v-if="section==='overview'" class="quick-compose mt32"><div><p class="eyebrow">KEEP CREATING</p><h2>记录一点新的东西。</h2><p class="hint mt16">写下文字，也可以加入照片、一段声音或视频。</p></div><button class="primary" @click="navigate('/creations/new')">开始创作 ↗</button></div></template><div v-else-if="!issue" class="empty"><p>暂无可显示的后端数据。</p><button @click="loadSection()">重新读取</button></div><footer class="admin-footer">XVYIN · 内容管理 <span>保存是草稿，发布才公开。</span></footer></div></main><ReleasePanel v-if="releaseOpen" :changes="releaseChanges" @close="releaseOpen=false" @activated="loadSection();notice='公开内容版本已切换，请打开网站检查。'" @preview="previewReleaseId=$event"/></div><div v-if="!authenticated" class="auth-overlay"><div class="auth-intro"><a href="/" class="brand-mark">虚宁</a><p>把日常，慢慢记下来。</p><span>XVYIN · PRIVATE STUDIO</span></div><section class="auth-card"><p class="eyebrow">ADMINISTRATOR</p><h1>{{authMode==='login'?'欢迎回来':authMode==='request'?'找回管理员密码':'设置新密码'}}</h1><p class="hint mt16">{{authMode==='login'?'使用管理员账号登录，访客无需注册。':authMode==='request'?'如果账号匹配，恢复邮件将发往已配置的管理员邮箱。':'请为管理员账号设置新的密码。'}}</p><div v-if="authIssue" class="notice error mt24" role="alert">{{authIssue}}</div><div v-if="recoverySent&&authMode==='request'" class="notice success mt24" role="status">恢复请求已提交。请检查管理员邮箱及垃圾邮件目录。</div><form class="mt32" @submit.prevent="submitAuth"><template v-if="authMode!=='confirm'"><label class="field">管理员账号<input v-model="loginUsername" name="username" autocomplete="username" required maxlength="64" spellcheck="false" autocapitalize="none"></label><label v-if="authMode==='login'" class="field mt24">密码<input v-model="password" type="password" name="password" autocomplete="current-password" required maxlength="1024"></label></template><template v-else><label class="field">新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><label class="field mt24">再次输入新密码<input v-model="confirmation" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><p class="hint mt16">15–128 个字符，建议使用密码管理器。</p></template><button class="primary full-width mt32" type="submit" :disabled="loginBusy">{{loginBusy?'正在处理…':authMode==='login'?'登录管理后台':authMode==='request'?'发送恢复邮件':'重设密码'}}</button></form><div class="flex between mt24"><button class="text-button" type="button" @click="authMode=authMode==='login'?'request':'login';authIssue='';recoverySent=false">{{authMode==='login'?'忘记密码':'返回登录'}}</button><a href="/">返回网站 ↗</a></div></section></div></div></template>
